    def process_response(self, value):
        if value.strip() == "fail":
            raise InvalidResponse("[red]Error![/red]")
        return value

def test_repro():
    console = Console(file=io.StringIO(), markup=False)
    # We need to simulate user input "fail" then "success"
    input_stream = io.StringIO("fail\nsuccess\n")

    print("Before ask")
    MyPrompt.ask("Enter something", console=console, stream=input_stream)

    output = console.file.getvalue()
    print(f"Output: {repr(output)}")

    if "[red]Error![/red]" in output:
        print("FAIL: Markup was printed raw")
    else:
        print("PASS: Markup was rendered")

if __name__ == "__main__":
    test_repro()
